<?php
declare(strict_types=1);
require_once __DIR__.'/includes/location-core.php';
require_once __DIR__.'/includes/media-core.php';
$user=app_require_auth();if(!app_has_permission('locations.manage',$user)){http_response_code(403);exit('You do not have permission to manage locations.');}
$pdo=app_pdo();$org=(int)$user['organization_id'];$error='';$locations=[];$ready=true;
try{$locations=location_list($pdo,$org,true);}catch(Throwable $e){$ready=false;$error='Location management needs the latest database upgrade. Run Upgrade once, then return here.';error_log('Location admin load failed: '.$e->getMessage());}
$mediaReady=$ready&&media_schema_ready($pdo);
if($ready&&$_SERVER['REQUEST_METHOD']==='POST'){
  try{
    if(!app_verify_csrf($_POST['csrf_token']??null))throw new RuntimeException('Your session token expired. Reload the page and try again.');
    $action=(string)($_POST['action']??'save');$id=max(0,(int)($_POST['id']??0));
    if($action==='save'){
      $payload=['name'=>$_POST['name']??'','public_slug'=>$_POST['public_slug']??'','address_line_1'=>$_POST['address_line_1']??'','address_line_2'=>$_POST['address_line_2']??'','city'=>$_POST['city']??'','state'=>$_POST['state']??'','postal_code'=>$_POST['postal_code']??'','country_code'=>$_POST['country_code']??'US','phone'=>$_POST['phone']??'','email'=>$_POST['email']??'','timezone'=>$_POST['timezone']??'America/Phoenix','status'=>$_POST['status']??'active','sort_order'=>(int)($_POST['sort_order']??0),'is_primary'=>isset($_POST['is_primary']),'dine_in_enabled'=>isset($_POST['dine_in_enabled']),'pickup_enabled'=>isset($_POST['pickup_enabled']),'delivery_enabled'=>isset($_POST['delivery_enabled']),'online_ordering_enabled'=>isset($_POST['online_ordering_enabled']),'delivery_radius_miles'=>$_POST['delivery_radius_miles']??'','delivery_minimum'=>$_POST['delivery_minimum']??'','delivery_fee'=>$_POST['delivery_fee']??'','pickup_lead_minutes'=>$_POST['pickup_lead_minutes']??20,'delivery_lead_minutes'=>$_POST['delivery_lead_minutes']??45,'latitude'=>$_POST['latitude']??'','longitude'=>$_POST['longitude']??''];
      if(isset($_POST['manage_hours'])){$hours=[];foreach(location_day_names() as $day=>$name)$hours[$day]=['is_closed'=>isset($_POST['hours'][$day]['is_closed']),'opens_at'=>$_POST['hours'][$day]['opens_at']??'','closes_at'=>$_POST['hours'][$day]['closes_at']??''];$payload['hours']=$hours;}
      $saved=location_save($pdo,$org,(int)$user['id'],$payload);app_redirect('locations-admin.php?saved=1&edit='.(int)$saved['id']);
    }
    if($id<1)throw new RuntimeException('Choose a location first.');
    if($action==='archive')location_archive($pdo,$org,$id,(int)$user['id']);elseif($action==='restore')location_restore($pdo,$org,$id,(int)$user['id']);elseif($action==='primary')location_set_primary($pdo,$org,$id,(int)$user['id']);else throw new RuntimeException('Unknown location action.');
    app_redirect('locations-admin.php?saved=1');
  }catch(Throwable $e){$error=$e->getMessage();try{$locations=location_list($pdo,$org,true);}catch(Throwable){}}
}
$editId=max(0,(int)($_GET['edit']??0));$editing=$editId&&$ready?location_get($pdo,$org,$editId):null;
$form=array_merge(['id'=>0,'name'=>'','public_slug'=>'','address_line_1'=>'','address_line_2'=>'','city'=>'','state'=>'','postal_code'=>'','country_code'=>'US','phone'=>'','email'=>'','timezone'=>'America/Phoenix','status'=>'active','is_primary'=>false,'sort_order'=>0,'dine_in_enabled'=>true,'pickup_enabled'=>true,'delivery_enabled'=>false,'online_ordering_enabled'=>false,'delivery_radius_miles'=>'','delivery_minimum'=>'','delivery_fee'=>'','pickup_lead_minutes'=>20,'delivery_lead_minutes'=>45,'latitude'=>'','longitude'=>'','hours'=>[]],$editing?:[]);
$hours=[];foreach(($form['hours']??[]) as $h)$hours[(int)$h['day_of_week']]=$h;$covers=$mediaReady?media_location_cover_map($pdo,$org):[];$cover=$editId?($covers[$editId]??''):'';
function lav(mixed $v):string{return app_escape((string)$v);}function lac(bool $v):string{return $v?' checked':'';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Locations | Restaurant Admin</title><link rel="stylesheet" href="assets/css/canonical-media.css?v=20260915-1"><style>:root{--line:#deded8;--ink:#171815;--muted:#6f726c;--accent:#d94a2b}*{box-sizing:border-box}body{margin:0;background:#f7f7f5;color:var(--ink);font:14px/1.45 Inter,system-ui,sans-serif}.shell{width:min(1180px,calc(100vw - 32px));margin:auto;padding:34px 0 70px}.eyebrow{font-size:10px;font-weight:900;letter-spacing:.12em;text-transform:uppercase;color:var(--accent)}h1{font-size:46px;margin:4px 0 8px}.layout{display:grid;grid-template-columns:330px 1fr;gap:22px;margin-top:24px}.panel,.location{background:#fff;border:1px solid var(--line);border-radius:16px;padding:18px}.location{margin-bottom:10px}.location img{width:100%;aspect-ratio:16/7;object-fit:cover;border-radius:10px;margin-bottom:10px}.location h3{margin:4px 0}.muted{color:var(--muted);font-size:11px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.btn{border:1px solid var(--line);border-radius:9px;background:#fff;color:var(--ink);padding:9px 11px;font-weight:800;text-decoration:none;cursor:pointer}.btn.primary{background:#171b1a;color:#fff;border-color:#171b1a}.btn.accent{background:var(--accent);color:#fff;border-color:var(--accent)}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{display:grid;gap:5px}.field.full{grid-column:1/-1}.field span,.section-title{font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.05em}.field input,.field select{width:100%;padding:10px;border:1px solid var(--line);border-radius:9px;background:#fff}.checks{display:grid;grid-template-columns:1fr 1fr;gap:8px}.check{padding:9px;border:1px solid var(--line);border-radius:9px}.section{margin-top:18px;padding-top:18px;border-top:1px solid var(--line)}.hours{display:grid;gap:7px;margin-top:10px}.hour{display:grid;grid-template-columns:95px 85px 1fr 1fr;gap:7px;align-items:center}.hour input[type=time]{padding:8px;border:1px solid var(--line);border-radius:8px}.notice,.error{padding:11px 13px;border-radius:10px;margin:12px 0}.notice{background:#eaf7ef}.error{background:#fff0ef;color:#9c3025}@media(max-width:820px){.layout,.fields,.checks{grid-template-columns:1fr}.field.full{grid-column:auto}.hour{grid-template-columns:1fr 80px 1fr 1fr}}</style></head><body><main class="shell"><div class="eyebrow">Store Network</div><h1>Locations</h1><p class="muted">Each store has its own cover image, address, hours and service controls. Menu products remain shared across locations.</p><?php if(($_GET['saved']??'')==='1'):?><div class="notice">Location settings saved.</div><?php endif;?><?php if($error):?><div class="error"><?=app_escape($error)?></div><?php endif;?><?php if($ready):?><div class="layout"><aside><div class="actions"><a class="btn accent" href="locations-admin.php">+ Add location</a><a class="btn" href="locations.php" target="_blank" rel="noopener">Public Locations ↗</a></div><?php foreach($locations as $loc):$id=(int)$loc['id'];?><article class="location"><?php if(!empty($covers[$id])):?><img src="<?=app_escape($covers[$id])?>" alt=""><?php endif;?><div class="eyebrow"><?=app_escape((string)$loc['status'])?><?=!empty($loc['is_primary'])?' · Primary':''?></div><h3><?=app_escape((string)$loc['name'])?></h3><div class="muted"><?=app_escape(trim(implode(', ',array_filter([(string)$loc['address_line_1'],(string)$loc['city'],(string)$loc['state']]))))?></div><div class="actions"><a class="btn" href="locations-admin.php?edit=<?=$id?>">Edit</a><?php if($loc['status']==='active'&&!$loc['is_primary']):?><form method="post"><input type="hidden" name="csrf_token" value="<?=app_escape(app_csrf_token())?>"><input type="hidden" name="action" value="primary"><input type="hidden" name="id" value="<?=$id?>"><button class="btn">Make primary</button></form><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=app_escape(app_csrf_token())?>"><input type="hidden" name="action" value="<?=$loc['status']==='active'?'archive':'restore'?>"><input type="hidden" name="id" value="<?=$id?>"><button class="btn"><?=$loc['status']==='active'?'Archive':'Restore'?></button></form></div></article><?php endforeach;?></aside><section class="panel"><div class="eyebrow"><?=$editing?'Edit Location':'Create Location'?></div><h2><?=$editing?app_escape((string)$editing['name']):'New restaurant location'?></h2><div class="location-cover-editor" id="locationCoverEditor" data-location-id="<?=(int)$form['id']?>" data-csrf="<?=app_escape(app_csrf_token())?>" data-manage="1"><div class="location-cover-row"><div class="cm-preview" data-cover-preview><?=$cover?'<img src="'.app_escape($cover).'" alt="Location cover">':'No cover'?></div><div class="cm-copy"><strong>Location cover image</strong><span>Unique to this location. The shared menu does not change.</span><div class="cm-status" data-cover-status><?=!$mediaReady?'Run Upgrade once to enable images.':($form['id']<1?'Save this location first, then add its cover image.':($cover?'Cover image active':'JPEG, PNG or WebP · max 10 MB'))?></div></div><div class="cm-actions"><button class="cm-btn primary" type="button" data-cover-upload <?=(!$mediaReady||$form['id']<1)?'disabled':''?>><?=$cover?'Replace':'Upload cover'?></button><button class="cm-btn danger" type="button" data-cover-remove <?=$cover?'':'hidden'?>>Remove</button></div></div></div><form method="post"><input type="hidden" name="csrf_token" value="<?=app_escape(app_csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)$form['id']?>"><input type="hidden" name="status" value="<?=lav($form['status'])?>"><div class="fields"><label class="field"><span>Name</span><input name="name" required maxlength="160" value="<?=lav($form['name'])?>"></label><label class="field"><span>Public slug</span><input name="public_slug" maxlength="180" value="<?=lav($form['public_slug'])?>"></label><label class="field full"><span>Address</span><input name="address_line_1" maxlength="200" value="<?=lav($form['address_line_1'])?>"></label><label class="field full"><span>Suite / Unit</span><input name="address_line_2" maxlength="200" value="<?=lav($form['address_line_2'])?>"></label><label class="field"><span>City</span><input name="city" maxlength="100" value="<?=lav($form['city'])?>"></label><label class="field"><span>State</span><input name="state" maxlength="100" value="<?=lav($form['state'])?>"></label><label class="field"><span>Postal code</span><input name="postal_code" maxlength="30" value="<?=lav($form['postal_code'])?>"></label><label class="field"><span>Country</span><input name="country_code" maxlength="2" value="<?=lav($form['country_code'])?>"></label><label class="field"><span>Phone</span><input name="phone" maxlength="40" value="<?=lav($form['phone'])?>"></label><label class="field"><span>Email</span><input name="email" type="email" maxlength="254" value="<?=lav($form['email'])?>"></label><label class="field"><span>Timezone</span><input name="timezone" maxlength="64" value="<?=lav($form['timezone'])?>"></label><label class="field"><span>Sort order</span><input name="sort_order" type="number" value="<?=lav($form['sort_order'])?>"></label><label class="field"><span>Latitude</span><input name="latitude" value="<?=lav($form['latitude'])?>"></label><label class="field"><span>Longitude</span><input name="longitude" value="<?=lav($form['longitude'])?>"></label></div><div class="section"><div class="section-title">Services</div><div class="checks"><label class="check"><input type="checkbox" name="is_primary"<?=lac((bool)$form['is_primary'])?>> Primary location</label><label class="check"><input type="checkbox" name="dine_in_enabled"<?=lac((bool)$form['dine_in_enabled'])?>> Dine-in</label><label class="check"><input type="checkbox" name="pickup_enabled"<?=lac((bool)$form['pickup_enabled'])?>> Pickup</label><label class="check"><input type="checkbox" name="delivery_enabled"<?=lac((bool)$form['delivery_enabled'])?>> Delivery</label><label class="check"><input type="checkbox" name="online_ordering_enabled"<?=lac((bool)$form['online_ordering_enabled'])?>> Online ordering</label></div></div><div class="section"><div class="section-title">Ordering</div><div class="fields"><label class="field"><span>Pickup lead minutes</span><input name="pickup_lead_minutes" type="number" min="0" max="1440" value="<?=lav($form['pickup_lead_minutes'])?>"></label><label class="field"><span>Delivery lead minutes</span><input name="delivery_lead_minutes" type="number" min="0" max="1440" value="<?=lav($form['delivery_lead_minutes'])?>"></label><label class="field"><span>Delivery radius miles</span><input name="delivery_radius_miles" type="number" min="0" step="0.01" value="<?=lav($form['delivery_radius_miles'])?>"></label><label class="field"><span>Delivery minimum</span><input name="delivery_minimum" type="number" min="0" step="0.01" value="<?=lav($form['delivery_minimum'])?>"></label><label class="field"><span>Delivery fee</span><input name="delivery_fee" type="number" min="0" step="0.01" value="<?=lav($form['delivery_fee'])?>"></label></div></div><div class="section"><label class="check"><input type="checkbox" name="manage_hours" checked> Manage location-specific hours</label><div class="hours"><?php foreach(location_day_names() as $day=>$dayName):$h=$hours[$day]??[];?><div class="hour"><strong><?=$dayName?></strong><label><input type="checkbox" name="hours[<?=$day?>][is_closed]"<?=!empty($h['is_closed'])?' checked':''?>> Closed</label><input type="time" name="hours[<?=$day?>][opens_at]" value="<?=app_escape(substr((string)($h['opens_at']??'11:00'),0,5))?>"><input type="time" name="hours[<?=$day?>][closes_at]" value="<?=app_escape(substr((string)($h['closes_at']??'21:00'),0,5))?>"></div><?php endforeach;?></div></div><div class="actions"><button class="btn primary" type="submit"><?=$editing?'Save Location':'Create Location'?></button></div></form></section></div><?php endif;?></main><script src="assets/js/location-media.js?v=20260915-1"></script><script src="js/universal-admin-page-shell.js?v=20260915-shell2"></script></body></html>
